"use client";
import type { RefObject } from "react";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisNavbarContent } from "./components/navbar/content";
import View2 from "./components/navbar/variants/03-morph";
const variants = {"morph":View2};
export type { ArtemisNavbarColumn, ArtemisNavbarContent, ArtemisNavbarLink, ArtemisNavbarMenu, ArtemisNavbarMenuLink } from "./components/navbar/content";
export interface ArtemisNavbarProps { className?: string; scrollContainer?: RefObject<HTMLElement | null>; variant?: "morph"; /** The words on the navbar; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisNavbarContent>; }
export function ArtemisNavbar({ className, variant = "morph", content }: ArtemisNavbarProps) {const View = variants[variant];return <ArtemisScope className={`art:relative art:z-40 ${className ?? ""}`}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** The words on a link or button, and where it goes. */
export interface ArtemisNavbarLink {
  label: string;
  href: string;
}

/** A link inside an open menu. */
export interface ArtemisNavbarMenuLink extends ArtemisNavbarLink {
  /** A short line under the label. morph and feature-morph. */
  description?: string;
  /** The card's icon. feature-morph, which keeps its own icon for that slot when you leave this out. */
  icon?: ComponentType<{ className?: string }>;
}

/** A small heading over a list of links, inside an open menu. */
export interface ArtemisNavbarColumn {
  title: string;
  links: ArtemisNavbarLink[];
}

/** A top-level item that opens a menu. */
export interface ArtemisNavbarMenu {
  label: string;
  /** Headed columns of links. pill-groups and mega-menu; morph and feature-morph list their links. */
  columns?: ArtemisNavbarColumn[];
  /** Links, each with an optional description and icon. morph and feature-morph; pill-groups and mega-menu show them as one column when `columns` is left out. feature-morph sets them in a fixed two-by-two panel, so four fill it. */
  links?: ArtemisNavbarMenuLink[];
  /** A highlighted card beside the columns. mega-menu. */
  feature?: { title: string; description: string; href: string };
}

/** The words on an Artemis navbar. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisNavbarContent {
  /** The name beside the logo mark, and where it links. All layouts. */
  brand: ArtemisNavbarLink;
  /** Items that open a menu, shown before `links`. pill-groups, mega-menu, morph and feature-morph. */
  menus?: ArtemisNavbarMenu[];
  /** Plain links in the bar. All layouts. The bars of morph and feature-morph have a fixed width: their own two one-word menus and two links fill them, and more or longer labels wrap or overflow. */
  links: ArtemisNavbarLink[];
  /** The quiet sign-in link. pill-groups, mega-menu, morph and feature-morph. */
  login?: ArtemisNavbarLink;
  /** A sign-up link beside sign-in. pill-groups. */
  signup?: ArtemisNavbarLink;
  /** The main button. All layouts. */
  cta: ArtemisNavbarLink;
  /** A line at the foot of an open menu, beside a link to `cta`. pill-groups and mega-menu. */
  menuNote?: string;
}

"use client";
// @zeus-internal
import { artemisEscapeDismiss } from "../../../lib/escape-dismiss";
import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { ChevronDown } from "lucide-react";
