import { Dropdown, MobileMenu, defaultMenus } from "./03-morph/menu";
import type { ArtemisNavbarContent } from "../content";
const DEFAULT = {
    brand: { label: "Artemis", href: "/" },
    menus: defaultMenus,
    links: [{ label: "Pricing", href: "#" }, { label: "Customers", href: "#" }],
    login: { label: "Sign in", href: "#" },
    cta: { label: "Get started", href: "#" },
} satisfies ArtemisNavbarContent;
export default function NavbarMorph({ content }: { content?: Partial<ArtemisNavbarContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const reduced = !!useReducedMotion();
    const bar = useRef<HTMLDivElement>(null);
    const nav = useRef<HTMLElement>(null);
    const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
    const [group, setGroup] = useState<number | null>(null);
    const [hover, setHover] = useState<string | null>(null);
    const [pill, setPill] = useState({ x: 0, width: 0 });
    const [x, setX] = useState(0);
    const [mobile, setMobile] = useState(false);
    const cancel = () => { if (timer.current)
        clearTimeout(timer.current); timer.current = null; };
    const leave = () => { cancel(); timer.current = setTimeout(() => setGroup(null), 90); };
    const select = (value: number | null, target: HTMLElement) => {
        cancel();
        if (value !== null && bar.current)
            setX(target.getBoundingClientRect().left - bar.current.getBoundingClientRect().left);
        setGroup(value);
    };
    const highlight = (value: string, target: HTMLElement) => {
        const box = target.getBoundingClientRect();
        const parent = nav.current?.getBoundingClientRect();
        if (parent)
            setPill({ x: box.left - parent.left, width: box.width });
        setHover(value);
    };
    useEffect(() => () => { if (timer.current)
        clearTimeout(timer.current); }, []);
    const press = { whileHover: reduced ? undefined : { scale: 1.01 }, whileTap: reduced ? undefined : { scale: 0.98 }, transition: ARTEMIS_SPRING_PRESS };
    return <header onKeyDown={event => artemisEscapeDismiss(event, () => { setMobile(false); setGroup(null); })} className="art:relative art:mx-auto art:w-full art:max-w-5xl">
            <div ref={bar} className="art:relative art:flex art:h-14 art:items-center art:justify-between art:rounded-full art:border art:border-border/60 art:bg-background/50 art:px-3 art:backdrop-blur-md art:@min-[640px]/artemis:px-4">
              <a href={copy.brand.href} className="art:flex art:shrink-0 art:items-center art:gap-2 art:rounded-lg art:px-1 art:font-semibold art:text-foreground art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-foreground/30">
                <span className="art:grid art:size-7 art:place-items-center art:bg-foreground art:text-background art:rounded-full">
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-hexagon art:size-4" aria-hidden="true">
                    <path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/>
                  </svg>
                </span>
                {copy.brand.label}
              </a>
              <nav ref={nav} className="art:-translate-x-1/2 art:absolute art:left-1/2 art:hidden art:items-center art:gap-1 art:@min-[1024px]/artemis:flex" onMouseLeave={() => { setHover(null); leave(); }}>
                <motion.span aria-hidden="true" className="art:pointer-events-none art:absolute art:top-0.5 art:bottom-0.5 art:left-0 art:rounded-full art:bg-muted" initial={{ width: 0, opacity: 0, x: 0 }} animate={reduced ? { opacity: hover ? 1 : 0 } : { ...pill, opacity: hover ? 1 : 0 }} transition={reduced ? { duration: 0 } : ARTEMIS_SPRING_PANEL}/>
                {copy.menus.map((menu, value) => <motion.button {...press} key={menu.label} type="button" className={`art:justify-center art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-auto art:p-0 art:hover:bg-transparent art:hover:text-inherit art:relative art:z-10 art:flex art:items-center art:gap-1 art:px-3 art:py-2 art:font-medium art:text-sm art:outline-none art:transition-colors art:focus-visible:ring-2 art:focus-visible:ring-foreground/30 ${group === value || hover === menu.label ? "art:text-foreground" : "art:text-muted-foreground"} art:rounded-full`} tabIndex={0} onMouseEnter={event => { highlight(menu.label, event.currentTarget); select(value, event.currentTarget); }} onClick={event => select(group === value ? null : value, event.currentTarget)}>
                  {menu.label}<ChevronDown className={`art:size-3.5 art:transition-transform art:duration-200${group === value ? " art:rotate-180" : ""}`}/>
                </motion.button>)}
                {copy.links.map(link => <a key={link.label} href={link.href} className={`art:relative art:z-10 art:rounded-lg art:px-3 art:py-2 art:font-medium art:text-sm art:outline-none art:transition-colors art:focus-visible:ring-2 art:focus-visible:ring-foreground/30 ${hover === link.label ? "art:text-foreground" : "art:text-muted-foreground"}`} onMouseEnter={event => { highlight(link.label, event.currentTarget); select(null, event.currentTarget); }}>{link.label}</a>)}
              </nav>
              <div className="art:flex art:items-center art:gap-2">
                <motion.a {...press} className="art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:gap-1.5 art:px-3 art:text-xs art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:hidden art:@min-[640px]/artemis:inline-flex art:h-9 art:rounded-full" href={copy.login.href} tabIndex={0}>
                  {copy.login.label}
                </motion.a>
                <motion.a {...press} className="art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-1.5 art:px-3 art:text-xs art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:hidden art:@min-[640px]/artemis:inline-flex art:h-9 art:rounded-full" href={copy.cta.href} tabIndex={0}>
                  {copy.cta.label}
                </motion.a>
                <motion.button {...press} type="button" className="art:items-center art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:p-0 art:font-normal art:hover:bg-transparent art:hover:text-inherit art:grid art:size-9 art:place-items-center art:text-foreground art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-foreground/30 art:@min-[1024px]/artemis:hidden art:rounded-full" aria-label={mobile ? "Close menu" : "Open menu"} aria-expanded={mobile} tabIndex={0} onClick={() => setMobile(!mobile)}>
                  <span className="art:relative art:block art:h-3.5 art:w-4">
                    <motion.span className="art:absolute art:top-0 art:left-0 art:h-0.5 art:w-full art:rounded-full art:bg-current" animate={{ y: mobile ? 6 : 0, rotate: mobile ? 45 : 0 }} transition={{ duration: reduced ? 0 : 0.25, ease: ARTEMIS_EASE_OUT }}/>
                    <motion.span className="art:absolute art:top-1.5 art:left-0 art:h-0.5 art:w-full art:rounded-full art:bg-current" animate={{ opacity: mobile ? 0 : 1 }} transition={{ duration: reduced ? 0 : 0.25, ease: ARTEMIS_EASE_OUT }}/>
                    <motion.span className="art:absolute art:bottom-0 art:left-0 art:h-0.5 art:w-full art:rounded-full art:bg-current" animate={{ y: mobile ? -6 : 0, rotate: mobile ? -45 : 0 }} transition={{ duration: reduced ? 0 : 0.25, ease: ARTEMIS_EASE_OUT }}/>
                  </span>
                </motion.button>
              </div>
              <AnimatePresence>{group !== null && copy.menus[group] && <Dropdown menu={copy.menus[group]} x={x} reduced={reduced} enter={cancel} leave={leave}/>}</AnimatePresence>
            </div>
            <AnimatePresence>{mobile && <MobileMenu menus={copy.menus} links={copy.links} login={copy.login} cta={copy.cta} reduced={reduced}/>}</AnimatePresence>
          </header>;
}

"use client";
// @zeus-internal
import { useRef, useState } from "react";
import { AnimatePresence, motion } from "motion/react";
import { ChevronDown } from "lucide-react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PANEL, ARTEMIS_SPRING_PRESS } from "../../../../lib/ease";
import type { ArtemisNavbarLink, ArtemisNavbarMenu, ArtemisNavbarMenuLink } from "../../content";
export const defaultMenus: ArtemisNavbarMenu[] = [
    { label: "Product", links: [
        { label: "Components", description: "Motion primitives and controls", href: "#" },
        { label: "Blocks", description: "Composed marketing sections", href: "#" },
        { label: "Templates", description: "Full pages, ready to ship", href: "#" },
        { label: "Agent kit", description: "Chat, tools, streaming surfaces", href: "#" },
    ] },
    { label: "Resources", links: [{ label: "Docs", href: "#" }, { label: "Changelog", href: "#" }, { label: "Guides", href: "#" }, { label: "Showcase", href: "#" }] },
];
/** A menu's links, or the links of all its columns. */
const linksOf = (menu: ArtemisNavbarMenu): ArtemisNavbarMenuLink[] => menu.links ?? menu.columns?.flatMap(column => column.links) ?? [];
export function Dropdown({ menu, x, reduced, enter, leave }: {
    menu: ArtemisNavbarMenu;
    x: number;
    reduced: boolean;
    enter: () => void;
    leave: () => void;
}) {
    const list = useRef<HTMLDivElement>(null);
    const [hovered, setHovered] = useState(false);
    const [rect, setRect] = useState({ x: 0, y: 0, width: 0, height: 0 });
    const links = linksOf(menu);
    const rich = links.some(item => item.description);
    return <motion.div className="art:absolute art:top-[calc(100%+0.5rem)] art:left-0 art:z-20" initial={reduced ? { opacity: 0 } : { opacity: 0, x, y: 6 }} animate={reduced ? { opacity: 1 } : { opacity: 1, x, y: 0 }} exit={reduced ? { opacity: 0 } : { opacity: 0, y: 6 }} transition={reduced ? { duration: 0 } : { opacity: { duration: 0.18, ease: ARTEMIS_EASE_OUT }, y: { duration: 0.18, ease: ARTEMIS_EASE_OUT }, x: ARTEMIS_SPRING_PANEL }} onMouseEnter={enter} onMouseLeave={() => { setHovered(false); leave(); }}>
    <motion.div layout={!reduced} transition={reduced ? { duration: 0 } : ARTEMIS_SPRING_PANEL} className="art:overflow-hidden art:rounded-2xl art:border art:border-border art:bg-background art:p-2">
      <div ref={list} className="art:relative" onMouseLeave={() => setHovered(false)}>
        <motion.span aria-hidden="true" className="art:pointer-events-none art:absolute art:top-0 art:left-0 art:rounded-xl art:bg-foreground/[0.07]" initial={false} animate={reduced ? { opacity: hovered ? 1 : 0 } : { ...rect, opacity: hovered ? 1 : 0 }} transition={reduced ? { duration: 0 } : ARTEMIS_SPRING_PANEL}/>
        <AnimatePresence initial={false} mode="popLayout">
          <motion.div key={menu.label} layout={!reduced} className={`art:grid art:gap-1 ${rich ? "art:grid-cols-2" : "art:grid-cols-1"}`} initial={{ opacity: 0, filter: "blur(4px)" }} animate={{ opacity: 1, filter: "blur(0px)" }} exit={{ opacity: 0, filter: "blur(4px)" }} transition={reduced ? { duration: 0 } : { opacity: { duration: 0.16, ease: ARTEMIS_EASE_OUT }, filter: { duration: 0.16, ease: ARTEMIS_EASE_OUT }, layout: ARTEMIS_SPRING_PANEL }}>
            {links.map(item => <a key={item.label} href={item.href} className={rich ? "art:relative art:z-10 art:block art:w-[15rem] art:rounded-xl art:p-3 art:outline-none art:focus-visible:bg-muted" : "art:relative art:z-10 art:block art:w-[12rem] art:rounded-lg art:px-3 art:py-2 art:font-medium art:text-foreground art:text-sm art:outline-none art:focus-visible:bg-muted"} onMouseEnter={event => {
                const box = event.currentTarget.getBoundingClientRect();
                const parent = list.current?.getBoundingClientRect();
                if (parent)
                    setRect({ x: box.left - parent.left, y: box.top - parent.top, width: box.width, height: box.height });
                setHovered(true);
            }}>
              {item.description ? <><span className="art:block art:font-medium art:text-foreground art:text-sm">{item.label}</span><span className="art:mt-0.5 art:block art:text-muted-foreground art:text-xs art:leading-5">{item.description}</span></> : item.label}
            </a>)}
          </motion.div>
        </AnimatePresence>
      </div>
    </motion.div>
  </motion.div>;
}
function Accordion({ menu, reduced }: {
    menu: ArtemisNavbarMenu;
    reduced: boolean;
}) {
    const [open, setOpen] = useState(false);
    return <div>
    <motion.button type="button" className="art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-auto art:p-0 art:hover:text-inherit art:flex art:w-full art:items-center art:justify-between art:px-3 art:py-2.5 art:font-medium art:text-foreground art:text-sm art:outline-none art:hover:bg-muted art:focus-visible:bg-muted art:rounded-full" aria-expanded={open} tabIndex={0} onClick={() => setOpen(!open)} whileHover={reduced ? undefined : { scale: 1.01 }} whileTap={reduced ? undefined : { scale: 0.98 }} transition={ARTEMIS_SPRING_PRESS}>
      {menu.label}<ChevronDown className={`art:size-4 art:text-muted-foreground art:transition-transform art:duration-200${open ? " art:rotate-180" : ""}`}/>
    </motion.button>
    <AnimatePresence initial={false}>{open && <motion.div className="art:overflow-hidden" initial={reduced ? { opacity: 0 } : { opacity: 0, height: 0 }} animate={reduced ? { opacity: 1 } : { opacity: 1, height: "auto" }} exit={reduced ? { opacity: 0 } : { opacity: 0, height: 0 }} transition={{ duration: reduced ? 0 : 0.26, ease: ARTEMIS_EASE_OUT }}>
      <div className="art:grid art:gap-0.5 art:py-1 art:pl-2">{linksOf(menu).map(item => <a key={item.label} href={item.href} className="art:block art:rounded-lg art:px-3 art:py-2 art:outline-none art:hover:bg-muted art:focus-visible:bg-muted"><span className="art:block art:font-medium art:text-foreground art:text-sm">{item.label}</span>{item.description ? <span className="art:block art:text-muted-foreground art:text-xs">{item.description}</span> : null}</a>)}</div>
    </motion.div>}</AnimatePresence>
  </div>;
}
export function MobileMenu({ menus, links, login, cta, reduced }: {
    menus: ArtemisNavbarMenu[];
    links: ArtemisNavbarLink[];
    login: ArtemisNavbarLink;
    cta: ArtemisNavbarLink;
    reduced: boolean;
}) {
    const press = { whileHover: reduced ? undefined : { scale: 1.01 }, whileTap: reduced ? undefined : { scale: 0.98 }, transition: ARTEMIS_SPRING_PRESS };
    return <motion.div className="art:absolute art:inset-x-0 art:top-full art:z-40 art:overflow-hidden art:@min-[1024px]/artemis:hidden" initial={reduced ? { opacity: 0 } : { opacity: 0, height: 0 }} animate={reduced ? { opacity: 1 } : { opacity: 1, height: "auto" }} exit={reduced ? { opacity: 0 } : { opacity: 0, height: 0 }} transition={{ duration: reduced ? 0 : 0.32, ease: ARTEMIS_EASE_OUT }}>
    <div className="art:mt-2 art:rounded-2xl art:border art:border-border/60 art:bg-background/95 art:p-2 art:backdrop-blur-md">
      {menus.map(menu => <Accordion key={menu.label} menu={menu} reduced={reduced}/>)}
      {links.map(link => <a key={link.label} href={link.href} className="art:block art:rounded-xl art:px-3 art:py-2.5 art:font-medium art:text-foreground art:text-sm art:outline-none art:hover:bg-muted art:focus-visible:bg-muted">{link.label}</a>)}
      <div className="art:mt-2 art:grid art:gap-2 art:p-1">
        <motion.a {...press} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:rounded-full" href={login.href} tabIndex={0}>{login.label}</motion.a>
        <motion.a {...press} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:rounded-full" href={cta.href} tabIndex={0}>{cta.label}</motion.a>
      </div>
    </div>
  </motion.div>;
}

// @zeus-internal
import type { KeyboardEvent } from "react";
export function artemisEscapeDismiss(event: KeyboardEvent<HTMLElement>, close: () => void) {
  if (event.key !== "Escape" || event.defaultPrevented) return;
  const triggers = [...event.currentTarget.querySelectorAll<HTMLButtonElement>('button[aria-expanded="true"]')];
  if (!triggers.length) return;
  const trigger = triggers.find(button => button.getClientRects().length > 0) ?? triggers[0];
  event.preventDefault();
  event.stopPropagation();
  close();
  trigger?.focus();
}
